use massive_feed::{auction_live::{Engine,trade_size},recording::Recording,Event,Market};
fn main()->Result<(),Box<dyn std::error::Error>>{
 let path=std::env::args().nth(1).ok_or("recording required")?;let rec=Recording::read(std::path::Path::new(&path))?;let mut engine=Engine::default();let mut expected=0.;let mut eligible=0;let mut future=0;let mut max_time=0;let mut seen=std::collections::BTreeSet::new();
 for row in &rec.records{if let Event::Trade{sym,p,s,t,q,metadata}=&row.event{if matches!(row.market,Market::Stocks)&&sym==&rec.symbol{max_time=max_time.max(*t).max(row.received_ms);if let Some(size)=trade_size(*s,metadata.ds.as_deref()) {engine.trade(sym,*p,size,*t,*q,&metadata.c,row.received_ms);if (*t<=row.received_ms+1000)&&row.received_ms.saturating_sub(*t)<=15000&&metadata.c.iter().all(|c|[0,12,37].contains(c))&&q.is_some()&&seen.insert(*q){expected+=size;eligible+=1;future+=usize::from(*t>row.received_ms);}}let _=engine.snapshot(sym,row.received_ms,true,vec![]);}}}
 let r=engine.snapshot(&rec.symbol,max_time+1,true,vec![]).ok_or("No profile")?;let actual=r["totalVolume"].as_f64().ok_or("No volume")?;assert!((actual-expected).abs()<1e-6);assert_eq!(r["acceptedTrades"].as_u64(),Some(eligible));let result=serde_json::json!({"symbol":rec.symbol,"records":rec.records.len(),"eligible":eligible,"futureDeferred":future,"expectedVolume":expected,"actualVolume":actual,"bins":r["bins"].as_array().map(|v|v.len()),"poc":[r["pocLow"].clone(),r["pocHigh"].clone()],"val":r["val"],"vah":r["vah"],"clockQueue":r["clockQueue"],"reading":r,"scope":"Real recorded partial window, causal replay; not full session history"});if let Some(output)=std::env::args().nth(2){std::fs::write(output,serde_json::to_vec_pretty(&result)?)?;}println!("{}",serde_json::json!({"eligible":eligible,"actualVolume":actual,"status":"passed"}));Ok(())}
